static void hex(const char *label, const BYTE *p, DWORD n) {
    printf("%s ", label);
    for (DWORD i = 0; i < n; i++) printf("%02x", p[i]);
    printf("\n");
}
static void dword_prop(NCRYPT_HANDLE h, const WCHAR *name, const char *label) {
    DWORD v = 0xdeadbeef, got = 0;
    SECURITY_STATUS r = NCryptGetProperty(h, name, (BYTE *)&v, sizeof v, &got, 0);
    printf("%s: %#lx size %lu value %lu\n", label, r, got, r ? 0 : v);
}
static void str_prop(NCRYPT_HANDLE h, const WCHAR *name, const char *label) {
    WCHAR v[64] = {0};
    DWORD got = 0;
    SECURITY_STATUS r = NCryptGetProperty(h, name, (BYTE *)v, sizeof v, &got, 0);
    printf("%s: %#lx size %lu %ls\n", label, r, got, r ? L"" : v);
}
static void export_size(NCRYPT_KEY_HANDLE k, const WCHAR *type, const char *label) {
    DWORD got = 0;
    SECURITY_STATUS r = NCryptExportKey(k, 0, type, NULL, NULL, 0, &got, 0);
    printf("export %s: %#lx size %lu\n", label, r, got);
}

static BYTE sha256_abc[32] = {0xba, 0x78, 0x16, 0xbf, 0x8f, 0x01, 0xcf, 0xea, 0x41, 0x41, 0x40, 0xde, 0x5d, 0xae, 0x22, 0x23,
                              0xb0, 0x03, 0x61, 0xa3, 0x96, 0x17, 0x7a, 0x9c, 0xb4, 0x10, 0xff, 0x61, 0xf2, 0x00, 0x15, 0xad};

static void rsa(NCRYPT_PROV_HANDLE prov) {
    NCRYPT_KEY_HANDLE k = 0, pub = 0;
    SECURITY_STATUS r = NCryptImportKey(prov, 0, BCRYPT_RSAFULLPRIVATE_BLOB, NULL, &k, (BYTE *)rsa_full, sizeof rsa_full, 0);
    printf("rsa import full: %#lx\n", r);
    dword_prop(k, NCRYPT_LENGTH_PROPERTY, "rsa length");
    dword_prop(k, BCRYPT_SIGNATURE_LENGTH, "rsa signature length");
    str_prop(k, NCRYPT_ALGORITHM_PROPERTY, "rsa algorithm");
    export_size(k, BCRYPT_RSAPUBLIC_BLOB, "rsa public");
    export_size(k, BCRYPT_RSAPRIVATE_BLOB, "rsa private (policy 0)");
    BYTE blob[1024];
    DWORD n = 0;
    r = NCryptExportKey(k, 0, BCRYPT_RSAPUBLIC_BLOB, NULL, blob, sizeof blob, &n, 0);
    printf("rsa public blob equal: %d\n", r == 0 && n == 24 + 3 + 128 && !memcmp(blob + 24, rsa_full + 24, 3 + 128));
    r = NCryptImportKey(prov, 0, BCRYPT_RSAPUBLIC_BLOB, NULL, &pub, blob, n, 0);
    printf("rsa import public: %#lx\n", r);

    /* PKCS#1 v1.5: deterministic */
    BCRYPT_PKCS1_PADDING_INFO p1 = {BCRYPT_SHA256_ALGORITHM};
    BYTE sig[512];
    DWORD sn = 0;
    r = NCryptSignHash(k, &p1, sha256_abc, 32, NULL, 0, &sn, NCRYPT_PAD_PKCS1_FLAG);
    printf("rsa sign size: %#lx %lu\n", r, sn);
    r = NCryptSignHash(k, &p1, sha256_abc, 32, sig, 10, &sn, NCRYPT_PAD_PKCS1_FLAG);
    printf("rsa sign short: %#lx %lu\n", r, sn);
    r = NCryptSignHash(k, &p1, sha256_abc, 32, sig, sizeof sig, &sn, NCRYPT_PAD_PKCS1_FLAG);
    printf("rsa sign: %#lx %lu\n", r, sn);
    hex("rsa pkcs1 sha256", sig, sn);
    printf("rsa verify (public key): %#lx\n", NCryptVerifySignature(pub, &p1, sha256_abc, 32, sig, sn, NCRYPT_PAD_PKCS1_FLAG));
    sig[7] ^= 1;
    printf("rsa verify tampered: %#lx\n", NCryptVerifySignature(pub, &p1, sha256_abc, 32, sig, sn, NCRYPT_PAD_PKCS1_FLAG));
    printf("rsa sign with public: %#lx\n", NCryptSignHash(pub, &p1, sha256_abc, 32, sig, sizeof sig, &sn, NCRYPT_PAD_PKCS1_FLAG));

    /* PSS: randomized */
    BCRYPT_PSS_PADDING_INFO pss = {BCRYPT_SHA256_ALGORITHM, 32};
    r = NCryptSignHash(k, &pss, sha256_abc, 32, sig, sizeof sig, &sn, NCRYPT_PAD_PSS_FLAG);
    printf("rsa pss sign: %#lx %lu\n", r, sn);
    printf("rsa pss verify: %#lx\n", NCryptVerifySignature(pub, &pss, sha256_abc, 32, sig, sn, NCRYPT_PAD_PSS_FLAG));
    pss.cbSalt = 20;
    printf("rsa pss verify other salt: %#lx\n", NCryptVerifySignature(pub, &pss, sha256_abc, 32, sig, sn, NCRYPT_PAD_PSS_FLAG));
    /* salts that cannot fit a 1024-bit key: the largest that fits is 128 - 32 - 2 */
    static const DWORD salts[] = {94, 95, 128, 129, 0x80000000, 0xffffffff};
    for (int i = 0; i < 6; i++) {
        pss.cbSalt = salts[i];
        sn = 0;
        r = NCryptSignHash(k, &pss, sha256_abc, 32, sig, sizeof sig, &sn, NCRYPT_PAD_PSS_FLAG);
        printf("rsa pss salt %#lx sign: %#lx %lu", salts[i], r, sn);
        printf(" verify: %#lx\n", NCryptVerifySignature(pub, &pss, sha256_abc, 32, sig, r ? 128 : sn, NCRYPT_PAD_PSS_FLAG));
    }

    /* OAEP with a label, PKCS#1 encryption, no padding */
    BCRYPT_OAEP_PADDING_INFO oaep = {BCRYPT_SHA256_ALGORITHM, (BYTE *)"label", 5};
    BYTE ct[256], pt[256];
    DWORD cn = 0, pn = 0;
    r = NCryptEncrypt(pub, (BYTE *)"secret", 6, &oaep, ct, sizeof ct, &cn, NCRYPT_PAD_OAEP_FLAG);
    printf("rsa oaep encrypt: %#lx %lu\n", r, cn);
    r = NCryptDecrypt(k, ct, cn, &oaep, pt, sizeof pt, &pn, NCRYPT_PAD_OAEP_FLAG);
    printf("rsa oaep decrypt: %#lx %lu %.*s\n", r, pn, (int)pn, r ? "" : (char *)pt);
    oaep.cbLabel = 4;
    r = NCryptDecrypt(k, ct, cn, &oaep, pt, sizeof pt, &pn, NCRYPT_PAD_OAEP_FLAG);
    printf("rsa oaep decrypt other label: %#lx\n", r);
    r = NCryptEncrypt(pub, (BYTE *)"secret", 6, NULL, ct, sizeof ct, &cn, NCRYPT_PAD_PKCS1_FLAG);
    printf("rsa pkcs1 encrypt: %#lx %lu\n", r, cn);
    r = NCryptDecrypt(k, ct, cn, NULL, NULL, 0, &pn, NCRYPT_PAD_PKCS1_FLAG);
    printf("rsa pkcs1 decrypt size: %#lx %lu\n", r, pn);
    r = NCryptDecrypt(k, ct, cn, NULL, pt, sizeof pt, &pn, NCRYPT_PAD_PKCS1_FLAG);
    printf("rsa pkcs1 decrypt: %#lx %lu %.*s\n", r, pn, (int)pn, r ? "" : (char *)pt);
    BYTE raw[128] = {0};
    raw[127] = 5;
    r = NCryptEncrypt(pub, raw, 128, NULL, ct, sizeof ct, &cn, NCRYPT_NO_PADDING_FLAG);
    printf("rsa raw encrypt: %#lx %lu\n", r, cn);
    r = NCryptDecrypt(k, ct, cn, NULL, pt, sizeof pt, &pn, NCRYPT_NO_PADDING_FLAG);
    printf("rsa raw decrypt: %#lx %lu last %d\n", r, pn, pn ? pt[pn - 1] : -1);
    NCryptFreeObject(pub);
    NCryptFreeObject(k);
}

static void ecdsa(NCRYPT_PROV_HANDLE prov, const WCHAR *alg, const char *label) {
    NCRYPT_KEY_HANDLE k = 0, pub = 0;
    SECURITY_STATUS r = NCryptCreatePersistedKey(prov, &k, alg, NULL, 0, 0);
    DWORD policy = NCRYPT_ALLOW_EXPORT_FLAG | NCRYPT_ALLOW_PLAINTEXT_EXPORT_FLAG;
    NCryptSetProperty(k, NCRYPT_EXPORT_POLICY_PROPERTY, (BYTE *)&policy, sizeof policy, 0);
    r = r ? r : NCryptFinalizeKey(k, 0);
    printf("%s create: %#lx\n", label, r);
    dword_prop(k, NCRYPT_LENGTH_PROPERTY, "  length");
    dword_prop(k, BCRYPT_SIGNATURE_LENGTH, "  signature length");
    str_prop(k, NCRYPT_ALGORITHM_GROUP_PROPERTY, "  group");
    export_size(k, BCRYPT_ECCPUBLIC_BLOB, "  public");
    export_size(k, BCRYPT_ECCPRIVATE_BLOB, "  private");
    BYTE blob[256], sig[256];
    DWORD n = 0, sn = 0;
    r = NCryptExportKey(k, 0, BCRYPT_ECCPUBLIC_BLOB, NULL, blob, sizeof blob, &n, 0);
    printf("  public magic %.4s\n", r ? "" : (char *)blob);
    r = NCryptImportKey(prov, 0, BCRYPT_ECCPUBLIC_BLOB, NULL, &pub, blob, n, 0);
    printf("  import public: %#lx\n", r);
    for (DWORD hl = 20; hl <= 64; hl += hl == 20 ? 12 : 16) {
        BYTE h[64];
        for (DWORD i = 0; i < hl; i++) h[i] = (BYTE)(i * 7 + 1);
        r = NCryptSignHash(k, NULL, h, hl, sig, sizeof sig, &sn, 0);
        SECURITY_STATUS v = NCryptVerifySignature(pub, NULL, h, hl, sig, sn, 0);
        h[0] ^= 1;
        SECURITY_STATUS bad = NCryptVerifySignature(pub, NULL, h, hl, sig, sn, 0);
        printf("  %lu-byte hash: sign %#lx %lu verify %#lx other hash %#lx\n", hl, r, sn, v, bad);
    }
    printf("  verify short signature: %#lx\n", NCryptVerifySignature(pub, NULL, sha256_abc, 32, sig, sn - 1, 0));
    printf("  sign with public: %#lx\n", NCryptSignHash(pub, NULL, sha256_abc, 32, sig, sizeof sig, &sn, 0));
    NCryptFreeObject(pub);
    NCryptFreeObject(k);
}

static void ecdh(NCRYPT_PROV_HANDLE prov) {
    NCRYPT_KEY_HANDLE a = 0, b = 0, bpub = 0;
    NCRYPT_SECRET_HANDLE s = 0, s2 = 0;
    printf("ecdh import a: %#lx\n", NCryptImportKey(prov, 0, BCRYPT_ECCPRIVATE_BLOB, NULL, &a, (BYTE *)ecdh_a, sizeof ecdh_a, 0));
    printf("ecdh import b: %#lx\n", NCryptImportKey(prov, 0, BCRYPT_ECCPRIVATE_BLOB, NULL, &b, (BYTE *)ecdh_b, sizeof ecdh_b, 0));
    BYTE pubb[8 + 64];
    memcpy(pubb, ecdh_b, sizeof pubb);
    pubb[3] = '1'; /* ECK1: the public blob */
    printf("ecdh import b public: %#lx\n", NCryptImportKey(prov, 0, BCRYPT_ECCPUBLIC_BLOB, NULL, &bpub, pubb, sizeof pubb, 0));
    str_prop(a, NCRYPT_ALGORITHM_PROPERTY, "ecdh algorithm");
    printf("ecdh agreement: %#lx\n", NCryptSecretAgreement(a, bpub, &s, 0));
    printf("ecdh agreement (b, a): %#lx\n", NCryptSecretAgreement(b, a, &s2, 0));
    BYTE out[128], out2[128];
    DWORD n = 0, n2 = 0;
    SECURITY_STATUS r = NCryptDeriveKey(s, BCRYPT_KDF_RAW_SECRET, NULL, NULL, 0, &n, 0);
    printf("raw size: %#lx %lu\n", r, n);
    r = NCryptDeriveKey(s, BCRYPT_KDF_RAW_SECRET, NULL, out, sizeof out, &n, 0);
    printf("raw: %#lx %lu\n", r, n);
    hex("raw secret", out, n);
    NCryptDeriveKey(s2, BCRYPT_KDF_RAW_SECRET, NULL, out2, sizeof out2, &n2, 0);
    printf("raw both ways equal: %d\n", n == n2 && !memcmp(out, out2, n));
    r = NCryptDeriveKey(s, BCRYPT_KDF_RAW_SECRET, NULL, out, 8, &n, 0);
    printf("raw into 8 bytes: %#lx %lu\n", r, n);
    hex("raw 8", out, n);

    BCryptBuffer bufs[4];
    BCryptBufferDesc desc = {BCRYPTBUFFER_VERSION, 0, bufs};
    r = NCryptDeriveKey(s, BCRYPT_KDF_HASH, NULL, out, sizeof out, &n, 0);
    printf("hash (no parameters): %#lx %lu\n", r, n);
    hex("hash default", out, n);
    bufs[0] = (BCryptBuffer){sizeof BCRYPT_SHA256_ALGORITHM, KDF_HASH_ALGORITHM, (void *)BCRYPT_SHA256_ALGORITHM};
    bufs[1] = (BCryptBuffer){3, KDF_SECRET_PREPEND, (void *)"pre"};
    bufs[2] = (BCryptBuffer){4, KDF_SECRET_APPEND, (void *)"post"};
    desc.cBuffers = 3;
    r = NCryptDeriveKey(s, BCRYPT_KDF_HASH, &desc, out, sizeof out, &n, 0);
    printf("hash sha256 pre/post: %#lx %lu\n", r, n);
    hex("hash sha256", out, n);
    bufs[3] = (BCryptBuffer){5, KDF_HMAC_KEY, (void *)"hmack"};
    desc.cBuffers = 4;
    r = NCryptDeriveKey(s, BCRYPT_KDF_HMAC, &desc, out, sizeof out, &n, 0);
    printf("hmac sha256 key: %#lx %lu\n", r, n);
    hex("hmac sha256", out, n);
    desc.cBuffers = 3;
    r = NCryptDeriveKey(s, BCRYPT_KDF_HMAC, &desc, out, sizeof out, &n, KDF_USE_SECRET_AS_HMAC_KEY_FLAG);
    printf("hmac secret as key: %#lx %lu\n", r, n);
    hex("hmac z", out, n);
    printf("unknown kdf: %#lx\n", NCryptDeriveKey(s, L"NOSUCH", NULL, out, sizeof out, &n, 0));
    printf("free secret: %#lx\n", NCryptFreeObject(s));
    printf("free secret again: %#lx\n", NCryptFreeObject(s));
    NCryptFreeObject(s2);
    NCryptFreeObject(a);
    NCryptFreeObject(b);
    NCryptFreeObject(bpub);
}

int main(void) {
    NCRYPT_PROV_HANDLE prov = 0;
    printf("open: %#lx\n", NCryptOpenStorageProvider(&prov, MS_KEY_STORAGE_PROVIDER, 0));
    rsa(prov);
    ecdsa(prov, BCRYPT_ECDSA_P256_ALGORITHM, "ecdsa p256");
    ecdsa(prov, BCRYPT_ECDSA_P384_ALGORITHM, "ecdsa p384");
    ecdsa(prov, BCRYPT_ECDSA_P521_ALGORITHM, "ecdsa p521");
    ecdh(prov);

    /* a fixed P-384 ECDSA key: its public half verifies what it signs */
    NCRYPT_KEY_HANDLE k = 0;
    SECURITY_STATUS r;
    printf("ecdsa384 import: %#lx\n", NCryptImportKey(prov, 0, BCRYPT_ECCPRIVATE_BLOB, NULL, &k, (BYTE *)ecdsa384, sizeof ecdsa384, 0));
    BYTE sig[128];
    DWORD sn = 0;
    r = NCryptSignHash(k, NULL, sha256_abc, 32, sig, sizeof sig, &sn, 0);
    printf("ecdsa384 sign: %#lx %lu\n", r, sn);
    printf("ecdsa384 verify: %#lx\n", NCryptVerifySignature(k, NULL, sha256_abc, 32, sig, sn, 0));
    BYTE bad[sizeof ecdsa384];
    memcpy(bad, ecdsa384, sizeof bad);
    bad[sizeof bad - 1] ^= 1;
    NCRYPT_KEY_HANDLE k2 = 0;
    printf("ecdsa384 import mismatched scalar: %#lx\n", NCryptImportKey(prov, 0, BCRYPT_ECCPRIVATE_BLOB, NULL, &k2, bad, sizeof bad, 0));
    if (k2) NCryptFreeObject(k2);
    printf("ecdsa384 import short: %#lx\n", NCryptImportKey(prov, 0, BCRYPT_ECCPRIVATE_BLOB, NULL, &k2, (BYTE *)ecdsa384, sizeof ecdsa384 - 1, 0));
    NCryptFreeObject(k);

    /* the generic ECDSA: the curve by name */
    k = 0;
    r = NCryptCreatePersistedKey(prov, &k, BCRYPT_ECDSA_ALGORITHM, NULL, 0, 0);
    printf("generic ecdsa create: %#lx\n", r);
    if (!r) {
        r = NCryptSetProperty(k, BCRYPT_ECC_CURVE_NAME, (BYTE *)BCRYPT_ECC_CURVE_NISTP384, sizeof BCRYPT_ECC_CURVE_NISTP384, 0);
        printf("generic ecdsa curve: %#lx\n", r);
        printf("generic ecdsa finalize: %#lx\n", NCryptFinalizeKey(k, 0));
        dword_prop(k, NCRYPT_LENGTH_PROPERTY, "generic ecdsa length");
        str_prop(k, BCRYPT_ECC_CURVE_NAME, "generic ecdsa curve name");
        NCryptFreeObject(k);
    }

    /* RSA blobs whose header sizes add up past 2^32 to the blob's length (32-bit sums wrap) */
    static const DWORD heads[][6] = {
        {0x33415352, 1024, 3, 0x80000000, 1, 1},
        {0x32415352, 1024, 3, 0xffffff00, 0x100, 0x20},
    };
    static const DWORD lens[] = {32, 59};
    for (int i = 0; i < 2; i++) {
        BYTE *b = calloc(1, lens[i] + 16);
        memcpy(b, heads[i], 24);
        memset(b + 24, 1, lens[i] - 24);
        const WCHAR *t = i == 0 ? BCRYPT_RSAFULLPRIVATE_BLOB : BCRYPT_RSAPRIVATE_BLOB;
        k = 0;
        printf("rsa import wrapping header %d: %#lx\n", i, NCryptImportKey(prov, 0, t, NULL, &k, b, lens[i], 0));
        if (k) NCryptFreeObject(k);
        free(b);
    }
    NCryptFreeObject(prov);
    return 0;
}
